\title{Finite Two-Colour Ramsey Theory: The Erd\H{o}s--Szekeres Bound and the Exact Value $R(3,3)=6$}
\author{Aristotle}
\date{June 20, 2026}

\begin{document}

\begin{abstract}
We present a self-contained, formally verified development of the elementary theory of
finite two-colour Ramsey numbers. A red/blue colouring of a complete graph is encoded by
a single simple graph $G$, the red edges being those of $G$ and the blue edges those of
its complement $G^{c}$. We define the arrow relation $\arrows{n}{s}{t}$ and establish
three pillars: monotonicity of the relation in the number of vertices; the
Erd\H{o}s--Szekeres inductive step, from which the binomial upper bound
$\binom{s+t}{s} \to (s+1,t+1)$ (equivalently $R(s+1,t+1) \le \binom{s+t}{s}$) follows by
double induction and Pascal's rule; and the exact value $R(3,3)=6$, obtained from the
binomial bound for the upper half and from the pentagon $C_5$ for the lower half. All
statements correspond to machine-checked theorems; we give their full statements and
proof sketches, and we close with the asymptotic landscape and a programme of future
extensions.
\end{abstract}

\maketitle

\section{Introduction}

Ramsey theory studies the inevitability of order in large structures. Its prototypical
statement concerns edge colourings of complete graphs: any sufficiently large complete
graph, with edges coloured in two colours, contains a monochromatic clique of prescribed
size. The least size at which this becomes unavoidable is the \emph{Ramsey number}
$R(s,t)$. This paper records a rigorous, formalized account of the first quantitative
results: monotonicity of the arrow relation (Proposition~\ref{prop:mono}), the
Erd\H{o}s--Szekeres recursion (Theorem~\ref{thm:step}) and the binomial upper bound
(Theorem~\ref{thm:rec}, Corollary~\ref{cor:bound}), and the exact value $R(3,3)=6$
(Theorems~\ref{thm:upper} and~\ref{thm:lower}). We claim only what is proved; the values
$R(3,4)=9$, $R(4,4)=18$, the diagonal probabilistic lower bound, and the Hales--Jewett
theorem are discussed as context and future work.

\section{The colouring model}

\begin{definition}[Two-colouring as a graph]
A red/blue colouring of the complete graph on a vertex type $V$ is a simple graph $G$ on
$V$. An edge $\{u,v\}$ is \emph{red} if $u \sim_G v$ and \emph{blue} if $u \sim_{G^{c}} v$,
where $G^{c}$ is the complement. Thus the red subgraph is $G$ and the blue subgraph is
$G^{c}$.
\end{definition}

\begin{definition}[Ambient type]
For the canonical setting on $s+t$ vertices we write
$\mathrm{ArrowsType}\,s\,t := \mathrm{SimpleGraph}(\mathrm{Fin}(s+t))$.
A \emph{red $s$-clique} is a set $S$ with $G.\IsNClique\,s\,S$; a \emph{blue $t$-clique}
is a set $S$ with $G^{c}.\IsNClique\,t\,S$.
\end{definition}

\begin{definition}[Arrow relation]
\label{def:arrows}
For $n,s,t \in \mathbb{N}$, the relation $\arrows{n}{s}{t}$ (formally $\mathrm{Arrows}\,n\,s\,t$)
holds iff for every vertex type $V$, every colouring $G$, and every finite vertex set $W$
with $|W| \ge n$, there exists $S \subseteq W$ that is a red $s$-clique or there exists
$S \subseteq W$ that is a blue $t$-clique:
\[
\arrows{n}{s}{t} :\equiv \forall V\,\forall G\,\forall W\,\bigl(|W|\ge n \Rightarrow
(\exists S\subseteq W,\ G.\IsNClique\,s\,S) \lor
(\exists S\subseteq W,\ G^{c}.\IsNClique\,t\,S)\bigr).
\]
Quantifying over an arbitrary vertex type with a finite subset $W$ bakes monotonicity in
the vertex count into the definition and lets the recursion operate on subsets of a fixed
ambient set.
\end{definition}

\begin{definition}[Ramsey number]
$R(s,t) := \min\{\, n : \arrows{n}{s}{t}\,\}$, the least threshold at which the arrow
relation holds.
\end{definition}

\section{Monotonicity}

\begin{proposition}[\texttt{Arrows.mono}]
\label{prop:mono}
If $\arrows{n}{s}{t}$ and $n \le n'$, then $\arrows{n'}{s}{t}$.
\end{proposition}

\begin{proof}[Proof sketch]
Let $|W| \ge n'$. Then $|W| \ge n' \ge n$, so the hypothesis applies to $W$ directly and
yields the required monochromatic clique.
\end{proof}

Equivalently, $N \mapsto \arrows{N}{s}{t}$ is upward closed, so $R(s,t)$ is attained and
$\arrows{n}{s}{t} \iff R(s,t) \le n$.

\section{Base cases}

\begin{lemma}[\texttt{arrows\_one\_red}]
\label{lem:onered}
For every $b$, $\arrows{1}{1}{b}$.
\end{lemma}

\begin{proof}[Proof sketch]
If $|W| \ge 1$, pick $v \in W$; the singleton $\{v\}$ is a red $1$-clique.
\end{proof}

\begin{lemma}[\texttt{arrows\_one\_blue}]
\label{lem:oneblue}
For every $a$, $\arrows{1}{a}{1}$.
\end{lemma}

\begin{proof}[Proof sketch]
Symmetric: $\{v\}$ is a blue $1$-clique in $G^{c}$.
\end{proof}

\section{The Erd\H{o}s--Szekeres recursion and the binomial bound}

\begin{theorem}[Inductive step, \texttt{arrows\_step}]
\label{thm:step}
Let $m,n \ge 1$. If $\arrows{m}{s}{t+1}$ and $\arrows{n}{s+1}{t}$, then
$\arrows{m+n}{s+1}{t+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $|W| \ge m+n$ and choose $v \in W$. Partition $W \setminus \{v\}$ into the red
neighbours $R = \{x : x \sim_G v\}$ and the blue neighbours $B = \{x : x \not\sim_G v\}$,
so $|R| + |B| = |W| - 1 \ge m+n-1$; hence $|R| \ge m$ or $|B| \ge n$.
If $|R| \ge m$, apply $\arrows{m}{s}{t+1}$ inside $R$: a blue $(t+1)$-clique finishes
immediately, while a red $s$-clique $S \subseteq R$ extends to the red $(s+1)$-clique
$S \cup \{v\}$ because every vertex of $R$ is red-adjacent to $v$. The case $|B| \ge n$ is
symmetric, building a blue $(t+1)$-clique by attaching $v$.
\end{proof}

\begin{theorem}[Binomial upper bound, \texttt{arrows\_recursion}]
\label{thm:rec}
For all $s,t \in \mathbb{N}$, $\;\binom{s+t}{s} \to (s+1, t+1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Double induction on $s$ and $t$. For $s=0$, $\binom{t}{0}=1$ and the claim is
$\arrows{1}{1}{t+1}$ (Lemma~\ref{lem:onered}). For $t=0$, $\binom{s+1}{s+1}=1$ and the
claim is $\arrows{1}{s+2}{1}$ (Lemma~\ref{lem:oneblue}). For the step, combine
$\binom{s+t+1}{s} \to (s+1,t+2)$ and $\binom{s+t+1}{s+1} \to (s+2,t+1)$ via
Theorem~\ref{thm:step}, using positivity of the binomial thresholds; Pascal's rule
$\binom{s+t+1}{s} + \binom{s+t+1}{s+1} = \binom{s+t+2}{s+1}$ gives the new threshold.
\end{proof}

\begin{corollary}[\texttt{arrows\_binomial\_bound}]
\label{cor:bound}
For all $s,t$, $\binom{s+t}{s} \to (s+1,t+1)$; equivalently $R(s+1,t+1) \le \binom{s+t}{s}$,
or in classical indices $R(s,t) \le \binom{s+t-2}{s-1}$.
\end{corollary}

\section{The exact value $R(3,3)=6$}

\begin{theorem}[Upper half, \texttt{arrows\_three\_three}]
\label{thm:upper}
$\arrows{6}{3}{3}$, hence $R(3,3) \le 6$.
\end{theorem}

\begin{proof}[Proof sketch]
Specialize Theorem~\ref{thm:rec} to $s=t=2$: $\binom{4}{2}=6$.
\end{proof}

\begin{definition}[Pentagon, \texttt{pentagon}]
\label{def:pentagon}
On $\mathrm{Fin}\,5 \cong \mathbb{Z}/5\mathbb{Z}$, let $\mathrm{pentagon}$ be the symmetric
closure of $a+1=b$, i.e.\ $a \sim b \iff a+1=b \lor b+1=a$ (mod $5$). This is the $5$-cycle
$C_5$, taken as the red subgraph; its complement is again a $5$-cycle.
\end{definition}

\begin{lemma}[\texttt{pentagon\_no\_triangle}]
\label{lem:pentred}
There is no $S$ with $\mathrm{pentagon}.\IsNClique\,3\,S$.
\end{lemma}

\begin{lemma}[\texttt{pentagon\_compl\_no\_triangle}]
\label{lem:pentblue}
There is no $S$ with $\mathrm{pentagon}^{c}.\IsNClique\,3\,S$.
\end{lemma}

\begin{proof}[Proof sketch of Lemmas~\ref{lem:pentred} and~\ref{lem:pentblue}]
A finite exhaustive check over all $3$-subsets of $\mathrm{Fin}\,5$. A $5$-cycle is
triangle-free, and the complement of $C_5$ on five vertices is again a $5$-cycle.
\end{proof}

\begin{theorem}[Lower half, \texttt{not\_arrows\_five\_three\_three}]
\label{thm:lower}
$\lnot\,\arrows{5}{3}{3}$, hence $R(3,3) > 5$.
\end{theorem}

\begin{proof}[Proof sketch]
If $\arrows{5}{3}{3}$ held, applying it to the pentagon colouring on all of
$\mathrm{Fin}\,5$ would produce a red or blue triangle, contradicting
Lemmas~\ref{lem:pentred} and~\ref{lem:pentblue}.
\end{proof}

\begin{corollary}
$R(3,3) = 6$.
\end{corollary}

\begin{proof}
Theorem~\ref{thm:upper} gives $R(3,3) \le 6$ and Theorem~\ref{thm:lower} gives
$R(3,3) \ge 6$.
\end{proof}

\section{Algorithms}

\textbf{Erd\H{o}s--Szekeres recursive upper-bound evaluator.} Compute an upper bound for
$R(s,t)$ via $f(s,t)=f(s-1,t)+f(s,t-1)$ with $f(1,t)=f(s,1)=1$, evaluating to
$\binom{s+t-2}{s-1}$; memoized this runs in $O(st)$ operations and yields $f(3,3)=6$.

\textbf{Exhaustive monochromatic-triangle certifier.} Given an explicit colouring of
$K_n$, enumerate all $\binom{n}{3}$ triples and test each for being monochromatic; this
certifies the pentagon lemmas and that every colouring of $K_6$ has a monochromatic
triangle.

\section{Applications and discussion}

Ramsey-type guarantees appear across social networks (any six people contain three mutual
acquaintances or three mutual strangers), data coincidences, monotone-subsequence results,
and lower bounds in complexity theory. Asymptotically the binomial bound gives
$R(s,s) = O(4^s)$ while Erd\H{o}s's probabilistic argument gives $R(s,s) > 2^{s/2}$;
closing this exponential gap is a famous open problem. Exact values are scarce:
$R(3,3)=6$, $R(3,4)=9$, $R(4,4)=18$, with $R(5,5) \in [43,48]$.

\section{Future directions}

A reusable $\mathrm{RamseyNumber}\,s\,t := \inf\{N : \arrows{N}{s}{t}\}$ with an
\texttt{IsLeast} characterization; the diagonal lower bound $R(s,s) > 2^{s/2}$ by a finite
counting argument over $\mathrm{SimpleGraph}(\mathrm{Fin}\,n)$; off-diagonal exact values
$R(3,4)=9$ (circulant graph on $\mathrm{Fin}\,8$) and $R(4,4)=18$ (Paley graph on
$\mathrm{Fin}\,17$); and the Hales--Jewett theorem.

