function ARROWS(n, s, t):
    E <- all edges (i,j), i<j, of K_n
    for mask in 0 .. 2^|E| - 1:
        red <- { E[k] : bit k of mask set }
        has_red  <- exists s-subset all-red
        has_blue <- exists t-subset all-blue (no red edge inside)
        if not (has_red or has_blue): return False   # escape colouring found
    return True

